/** Anonymous direct messages (spec 3.7). */
import type { AnonymousIdentity, IsoDateString } from './common';

export interface Conversation {
  id: string;
  /** The other participant, shown only as an anonymous identity. */
  peer: AnonymousIdentity;
  lastMessagePreview: string | null;
  lastMessageAt: IsoDateString | null;
  unreadCount: number;
}

export type MessageDirection = 'outgoing' | 'incoming';

export interface Message {
  id: string;
  conversationId: string;
  body: string;
  direction: MessageDirection;
  createdAt: IsoDateString;
  /**
   * Idempotency key generated by the client before the first send attempt and
   * reused on every retry. The server returns the already-stored message
   * instead of creating a second one, so a retry after an ambiguous failure
   * cannot produce a duplicate.
   */
  clientMessageId: string | null;
}

export interface SendMessageInput {
  body: string;
  clientMessageId: string;
}

/** Starting a conversation from a post author's anonymous avatar. */
export interface StartConversationInput {
  /** `AnonymousIdentity.id` of the author, not their user id. */
  anonymousId: string;
}
